class _CanonicalJsonStream:
    """Incremental tokenizer for canonical compact JSON documents.

    Wraps a binary file object and parses exactly the JSON produced by
    :meth:`BranchStore._canonical_json`: no whitespace anywhere, strings
    escaped exactly as ``json.dumps(..., ensure_ascii=False)`` emits them,
    numbers in their canonical ``repr`` form. Every deviation raises
    :class:`ValueError`, so a document accepted by this tokenizer
    byte-for-byte equals its own canonical re-serialization. Only a fixed
    read buffer plus the current token are held in memory, never the whole
    document.
    """

    _CHUNK_SIZE = 65536

    __slots__ = ("_file", "_buffer", "_start", "_pos", "_eof")

    def __init__(self, fileobj: Any) -> None:
        self._file = fileobj
        self._buffer = b""
        self._start = 0
        self._pos = 0
        self._eof = False

    @property
    def offset(self) -> int:
        """Absolute byte offset of the next unparsed byte."""
        return self._start + self._pos

    def _fill(self) -> None:
        if self._eof:
            return
        if self._pos:
            self._buffer = self._buffer[self._pos:]
            self._start += self._pos
            self._pos = 0
        chunk = self._file.read(self._CHUNK_SIZE)
        if chunk:
            self._buffer += chunk
        else:
            self._eof = True

    def peek(self) -> int | None:
        """The next byte, or ``None`` at end of input."""
        while self._pos >= len(self._buffer) and not self._eof:
            self._fill()
        if self._pos >= len(self._buffer):
            return None
        return self._buffer[self._pos]

    def take(self) -> int:
        """Consume and return the next byte; EOF raises ValueError."""
        byte = self.peek()
        if byte is None:
            raise ValueError(
                "recovery chain is not valid JSON: unexpected end of "
                "document"
            )
        self._pos += 1
        return byte

    def at_end(self) -> bool:
        return self.peek() is None

    def expect(self, byte: int) -> None:
        got = self.take()
        if got != byte:
            raise ValueError(
                "recovery chain is not valid JSON: unexpected content"
            )

    def expect_literal(self, word: bytes) -> None:
        for expected in word:
            if self.take() != expected:
                raise ValueError(
                    "recovery chain is not valid JSON: invalid literal"
                )

    def parse_string(self) -> str:
        raw = bytearray()
        raw.append(self.take())  # opening quote (caller checked)
        while True:
            byte = self.take()
            raw.append(byte)
            if byte == 0x22:  # '"'
                break
            if byte == 0x5C:  # '\\'
                raw.append(self.take())
        try:
            text = bytes(raw).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(
                f"recovery chain is not valid UTF-8: {exc}"
            ) from exc
        try:
            value = json.loads(text)
        except ValueError as exc:
            raise ValueError(
                f"recovery chain is not valid JSON: {exc}"
            ) from exc
        if json.dumps(value, ensure_ascii=False, allow_nan=False) != text:
            raise ValueError(
                "recovery chain is not canonical compact JSON"
            )
        return value

    def parse_number(self) -> int | float:
        raw = bytearray()
        while True:
            byte = self.peek()
            if byte is None or not (
                0x30 <= byte <= 0x39 or byte in b"+-.eE"
            ):
                break
            raw.append(self.take())
        if not raw:
            raise ValueError(
                "recovery chain is not valid JSON: expected a number"
            )
        text = bytes(raw).decode("ascii")
        try:
            value = json.loads(text)
        except ValueError as exc:
            raise ValueError(
                f"recovery chain is not valid JSON: {exc}"
            ) from exc
        if json.dumps(value, ensure_ascii=False, allow_nan=False) != text:
            raise ValueError(
                "recovery chain is not canonical compact JSON"
            )
        return value

    def skip_value(self) -> None:
        byte = self.peek()
        if byte == 0x22:
            self.parse_string()
            return
        if byte == 0x7B:  # '{'
            self.take()
            if self.peek() == 0x7D:
                self.take()
                return
            seen: set[str] = set()
            while True:
                if self.peek() != 0x22:
                    raise ValueError(
                        "recovery chain is not valid JSON: expected an "
                        "object key"
                    )
                key = self.parse_string()
                if key in seen:
                    raise ValueError(
                        f"duplicate key {key!r} in JSON object"
                    )
                seen.add(key)
                self.expect(0x3A)
                self.skip_value()
                byte = self.take()
                if byte == 0x2C:
                    continue
                if byte == 0x7D:
                    return
                raise ValueError(
                    "recovery chain is not valid JSON: unexpected content"
                )
        if byte == 0x5B:  # '['
            self.take()
            if self.peek() == 0x5D:
                self.take()
                return
            while True:
                self.skip_value()
                byte = self.take()
                if byte == 0x2C:
                    continue
                if byte == 0x5D:
                    return
                raise ValueError(
                    "recovery chain is not valid JSON: unexpected content"
                )
        if byte == 0x74:
            self.expect_literal(b"true")
            return
        if byte == 0x66:
            self.expect_literal(b"false")
            return
        if byte == 0x6E:
            self.expect_literal(b"null")
            return
        if byte is not None and (0x30 <= byte <= 0x39 or byte == 0x2D):
            self.parse_number()
            return
        raise ValueError(
            "recovery chain is not valid JSON: unexpected content"
        )
```

