    @classmethod
    def _open_recovery_chain_locked(cls, path: str):
        """Open the chain file for reading while holding the chain lock,
        returning a binary file object positioned at the start.

        The file identity is re-checked inside the lock: the path is
        statted, opened, and the open descriptor statted again; if the
        directory entry was swapped between the two (a non-cooperating
        writer), the open is retried, and if it keeps racing the call
        raises :class:`OSError`. Because appends replace the chain
        atomically under the same lock, the returned descriptor only ever
        exposes the complete chain from before or after an append. A
        missing or unreadable file raises :class:`OSError`.
        """
        for _attempt in range(3):
            identity = os.stat(path)
            fileobj = open(path, "rb")
            current = os.fstat(fileobj.fileno())
            if (
                current.st_dev == identity.st_dev
                and current.st_ino == identity.st_ino
            ):
                return fileobj
            fileobj.close()
        raise OSError(
            f"recovery chain file is unstable: {path!r}"
        )
