    @classmethod
    def _scan_recovery_chain(
        cls, fileobj: Any, on_frame: Any
    ) -> tuple[int, int, str]:
        """Stream the open chain file, fully authenticating every frame
        while holding only one frame in memory.

        ``on_frame`` is invoked once per frame, in order, with a detached
        mapping carrying ``seq``, ``prev``, ``record``, ``digest``,
        ``body`` (the parsed audit body), ``offset`` and ``length`` (the
        frame's byte boundaries in the file); what the callback keeps is
        what bounds the caller's memory. Returns the chain's schema
        ``version``, frame count and head digest. Every content defect
        raises :class:`ValueError`; reading failures propagate as
        :class:`OSError`.
        """
        stream = _CanonicalJsonStream(fileobj)
        if stream.peek() is None:
            raise ValueError("recovery chain document is empty")
        if stream.peek() == 0xEF:
            bom = bytes((stream.take(), stream.take(), stream.take()))
            if bom == b"\xef\xbb\xbf":
                raise ValueError(
                    "recovery chain must be UTF-8 without a BOM"
                )
            raise ValueError(
                "recovery chain is not valid JSON: unexpected content"
            )
        stream.expect(0x7B)  # '{'
        seen: set[str] = set()
        format_value: Any = None
        version_value: Any = None
        count = 0
        previous_digest = cls._RECOVERY_CHAIN_GENESIS_PREV
        head = ""
        if stream.peek() == 0x7D:  # '}'
            stream.take()
        else:
            while True:
                if stream.peek() != 0x22:
                    raise ValueError(
                        "recovery chain is not valid JSON: expected an "
                        "object key"
                    )
                key = stream.parse_string()
                if key in seen:
                    raise ValueError(
                        f"duplicate key {key!r} in JSON object"
                    )
                seen.add(key)
                stream.expect(0x3A)  # ':'
                if key == "frames":
                    stream.expect(0x5B)  # '['
                    if stream.peek() == 0x5D:  # ']'
                        stream.take()
                    else:
                        while True:
                            frame_offset = stream.offset
                            fields = cls._parse_chain_frame_stream(stream)
                            frame_length = stream.offset - frame_offset
                            count += 1
                            body, digest = cls._validate_chain_frame_fields(
                                fields, count, previous_digest
                            )
                            previous_digest = digest
                            head = digest
                            on_frame(
                                {
                                    "seq": count,
                                    "prev": fields["prev"],
                                    "record": fields["record"],
                                    "digest": digest,
                                    "body": body,
                                    "offset": frame_offset,
                                    "length": frame_length,
                                }
                            )
                            byte = stream.take()
                            if byte == 0x2C:  # ','
                                continue
                            if byte == 0x5D:  # ']'
                                break
                            raise ValueError(
                                "recovery chain is not valid JSON: "
                                "unexpected content"
                            )
                elif key == "format":
                    if stream.peek() == 0x22:
                        format_value = stream.parse_string()
                    else:
                        stream.skip_value()
                elif key == "version":
                    version_value = stream.parse_number()
                else:
                    stream.skip_value()
                byte = stream.take()
                if byte == 0x2C:  # ','
                    continue
                if byte == 0x7D:  # '}'
                    break
                raise ValueError(
                    "recovery chain is not valid JSON: unexpected content"
                )
        if not stream.at_end():
            raise ValueError(
                "recovery chain is not valid JSON: trailing data"
            )
        if seen != set(cls._RECOVERY_CHAIN_KEYS):
            raise ValueError(
                "recovery chain must contain exactly the keys 'format', "
                "'version' and 'frames'"
            )
        if format_value != cls._RECOVERY_CHAIN_FORMAT:
            raise ValueError("recovery chain has an unknown format")
        if isinstance(version_value, bool) or not isinstance(
            version_value, int
        ):
            raise ValueError("recovery chain 'version' must be an int")
        if version_value not in cls._RECOVERY_CHAIN_SUPPORTED_VERSIONS:
            raise ValueError(
                f"unsupported recovery chain version {version_value!r}"
            )
        if not count:
            raise ValueError("recovery chain document has no frames")
        return version_value, count, head
