    @classmethod
    def _build_recovery_audit_index_locked(
        cls, path: str, index_path: str
    ) -> str:
        """Stream-authenticate the chain and durably publish its index;
        the caller holds the chain lock. Returns the chain head digest.

        The index is written entry by entry as frames stream past, so no
        more than one frame is ever materialized; the bytes are UTF-8
        (no BOM), compact JSON with no trailing newline, identical for
        identical chains. The temporary file lives in the index's
        directory, is flushed, fsync-ed and atomically replaced onto
        ``index_path`` with directory syncs, and is removed on every
        failure path; the chain file is never opened for writing.
        """
        chain_file = cls._open_recovery_chain_locked(path)
        try:
            directory = os.path.dirname(os.path.abspath(index_path))
            fd, tmp_path = tempfile.mkstemp(
                prefix=".recovery-chain-index-",
                suffix=".tmp",
                dir=directory,
            )
            published = False
            try:
                with os.fdopen(fd, "wb") as handle:
                    header = (
                        b'{"format":"'
                        + cls._RECOVERY_CHAIN_INDEX_FORMAT.encode("ascii")
                        + b'","version":'
                        + str(cls._RECOVERY_CHAIN_INDEX_VERSION).encode("ascii")
                        + b',"entries":['
                    )
                    handle.write(header)
                    first = True

                    def on_frame(frame: dict[str, Any]) -> None:
                        nonlocal first
                        entry = {
                            "seq": frame["seq"],
                            "offset": frame["offset"],
                            "length": frame["length"],
                            "digest": frame["digest"],
                        }
                        if not first:
                            handle.write(b",")
                        handle.write(
                            cls._canonical_json(entry).encode("utf-8")
                        )
                        first = False

                    version, count, head = cls._scan_recovery_chain(
                        chain_file, on_frame
                    )
                    trailer = (
                        '],"chain_version":%d,"frames":%d,"head":"%s"}'
                        % (version, count, head)
                    )
                    handle.write(trailer.encode("ascii"))
                    handle.flush()
                    os.fsync(handle.fileno())
                cls._fsync_directory(directory)
                os.replace(tmp_path, index_path)
                published = True
                cls._fsync_directory(directory)
            finally:
                if not published:
                    with contextlib.suppress(OSError):
                        os.remove(tmp_path)
        finally:
            chain_file.close()
        return head
```

