    @classmethod
    def _read_recovery_chain_index(
        cls, index_path: str
    ) -> tuple[int, int, str] | None:
        """Read and fully validate the index, returning its binding --
        ``(chain_version, frames, head)`` -- or ``None`` when the index
        is missing, unreadable or defective in any way. The index is a
        disposable cache, so no index problem ever raises here: it only
        ever triggers a rebuild from the canonical chain. Only a fixed
        amount of memory is used regardless of the entry count."""
        try:
            with open(index_path, "rb") as fileobj:
                stream = _CanonicalJsonStream(fileobj)
                if stream.peek() is None or stream.peek() == 0xEF:
                    return None
                stream.expect(0x7B)  # '{'
                seen: set[str] = set()
                format_value: Any = None
                version_value: Any = None
                chain_version: Any = None
                declared_frames: Any = None
                head: Any = None
                count = 0
                last_digest: str | None = None
                if stream.peek() == 0x7D:  # '}'
                    stream.take()
                else:
                    while True:
                        if stream.peek() != 0x22:
                            raise ValueError("expected an object key")
                        key = stream.parse_string()
                        if key in seen:
                            raise ValueError("duplicate key")
                        seen.add(key)
                        stream.expect(0x3A)  # ':'
                        if key == "entries":
                            count, last_digest = cls._scan_index_entries(stream)
                        elif key in ("format", "head"):
                            if stream.peek() != 0x22:
                                raise ValueError("expected a string")
                            value = stream.parse_string()
                            if key == "format":
                                format_value = value
                            else:
                                head = value
                        elif key in ("version", "chain_version", "frames"):
                            value = stream.parse_number()
                            if key == "version":
                                version_value = value
                            elif key == "chain_version":
                                chain_version = value
                            else:
                                declared_frames = value
                        else:
                            stream.skip_value()
                        byte = stream.take()
                        if byte == 0x2C:
                            continue
                        if byte == 0x7D:
                            break
                        raise ValueError("unexpected content")
                if not stream.at_end():
                    return None
                if seen != set(cls._RECOVERY_CHAIN_INDEX_KEYS):
                    return None
                if format_value != cls._RECOVERY_CHAIN_INDEX_FORMAT:
                    return None
                if (
                    isinstance(version_value, bool)
                    or not isinstance(version_value, int)
                    or version_value not in cls._RECOVERY_CHAIN_INDEX_SUPPORTED_VERSIONS
                ):
                    return None
                if (
                    isinstance(chain_version, bool)
                    or not isinstance(chain_version, int)
                    or chain_version not in cls._RECOVERY_CHAIN_SUPPORTED_VERSIONS
                ):
                    return None
                if (
                    isinstance(declared_frames, bool)
                    or not isinstance(declared_frames, int)
                    or declared_frames != count
                    or count < 1
                ):
                    return None
                if (
                    not isinstance(head, str)
                    or len(head) != 64
                    or set(head) - cls._HEX_DIGITS
                    or head != last_digest
                ):
                    return None
                return chain_version, declared_frames, head
        except (OSError, ValueError):
            return None
