    @classmethod
    def _scan_index_entries(
        cls, stream: _CanonicalJsonStream
    ) -> tuple[int, str | None]:
        """Stream the index's ``entries`` array, validating each entry's
        shape, consecutive numbering and digest evidence; return the
        entry count and the last entry's digest. Any defect raises
        :class:`ValueError`, which the caller treats as a corrupt index."""
        stream.expect(0x5B)  # '['
        count = 0
        last_digest: str | None = None
        if stream.peek() == 0x5D:  # ']'
            stream.take()
            return count, last_digest
        while True:
            stream.expect(0x7B)  # '{'
            fields: dict[str, Any] = {}
            if stream.peek() == 0x7D:
                stream.take()
            else:
                while True:
                    if stream.peek() != 0x22:
                        raise ValueError("expected an entry key")
                    key = stream.parse_string()
                    if key in fields:
                        raise ValueError("duplicate key")
                    stream.expect(0x3A)  # ':'
                    if key in ("seq", "offset", "length"):
                        fields[key] = stream.parse_number()
                    elif key == "digest":
                        if stream.peek() != 0x22:
                            raise ValueError("expected a string")
                        fields[key] = stream.parse_string()
                    else:
                        stream.skip_value()
                        fields[key] = None
                    byte = stream.take()
                    if byte == 0x2C:
                        continue
                    if byte == 0x7D:
                        break
                    raise ValueError("unexpected content")
            if set(fields.keys()) != set(cls._RECOVERY_CHAIN_INDEX_ENTRY_KEYS):
                raise ValueError("bad entry keys")
            count += 1
            seq = fields["seq"]
            if isinstance(seq, bool) or not isinstance(seq, int) or seq != count:
                raise ValueError("bad entry sequence")
            for name in ("offset", "length"):
                value = fields[name]
                if (
                    isinstance(value, bool)
                    or not isinstance(value, int)
                    or value < 0
                ):
                    raise ValueError("bad entry boundary")
            digest = fields["digest"]
            if len(digest) != 64 or set(digest) - cls._HEX_DIGITS:
                raise ValueError("bad entry digest")
            last_digest = digest
            byte = stream.take()
            if byte == 0x2C:
                continue
            if byte == 0x5D:  # ']'
                break
            raise ValueError("unexpected content")
        return count, last_digest
