    @classmethod
    def _indexed_chain_scan(
        cls,
        path: str,
        index_path: str,
        wanted: set[int] | None,
    ) -> tuple[int, str, dict[int, dict[str, Any]]]:
        """Authenticate the chain with bounded memory under the chain
        lock, keep the index fresh, and return the frame count, the head
        digest and the audit bodies of the ``wanted`` sequence numbers.

        The chain is streamed and fully authenticated exactly as
        :meth:`_load_recovery_chain` parses it, but only one frame is
        ever materialized, plus the bodies the caller asked for. The
        index is then re-read and, whenever it is missing, stale or
        defective, rebuilt once from the just-authenticated canonical
        chain; the chain remains the only trusted source and the index
        never answers a query by itself.
        """
        lock_path = cls._recovery_chain_lock_path(path)
        fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o644)
        try:
            cls._acquire_chain_lock(fd, None)
            try:
                captured: dict[int, dict[str, Any]] = {}

                def on_frame(frame: dict[str, Any]) -> None:
                    if wanted is not None and frame["seq"] in wanted:
                        captured[frame["seq"]] = frame["body"]

                chain_file = cls._open_recovery_chain_locked(path)
                try:
                    version, count, head = cls._scan_recovery_chain(
                        chain_file, on_frame
                    )
                finally:
                    chain_file.close()
                binding = cls._read_recovery_chain_index(index_path)
                if binding != (version, count, head):
                    cls._build_recovery_audit_index_locked(path, index_path)
                return count, head, captured
            finally:
                cls._release_chain_lock(fd)
        finally:
            os.close(fd)
